@startuml

class Organizer {
  + firstName : string
  + lastName : string
  + email : string
  + postalAddress : string
  + phoneNumber : string
  + password : string
}

class EventType {
  + name : string
}

class Event {
  + occasion : string
  + startDateTime : datetime
  + endDateTime : datetime
}

class Location {
  + name : string
  + address : string
}

class Attendee {
  + firstName : string
  + lastName : string
  + email : string
  + password : string
  + attendanceStatus : string
}

class Task {
  + description : string
  + status : string
}

class EventTask {
  + status : string
}

class TaskAssignment {
}

Organizer "1..*" -- "1..*" Event : organizes
Organizer "0..*" -- "0..*" Event : attends
Organizer "1" -- "0..*" EventType : creates
Event "1" -- "1" EventType : is of type
Event "1" -- "1" Location : at
Event "1" *-- "0..*" EventTask : has checklist
Task "1" -- "0..*" EventTask : template for
Attendee "0..*" -- "0..*" Event : invited to
Attendee "1" -- "0..*" TaskAssignment : performs
EventTask "1" -- "0..*" TaskAssignment : is assigned to

@enduml

